<?php
namespace App\Services;
use Illuminate\Database\Eloquent\Builder; use Illuminate\Http\Request; use Illuminate\Support\Collection;
class SkiRackProductFilter { public function values(Request $r):array{return ['manufacturers'=>$this->numbers($r->input('manufacturer')),'price_from'=>$this->number($r->input('price_from')),'price_to'=>$this->number($r->input('price_to')),'availability'=>array_values(array_intersect($this->strings($r->input('availability')),['in_stock','to_order'])),'ski_pairs'=>$this->numbers($r->input('ski_pairs')),'snowboards'=>$this->numbers($r->input('snowboard'))];} public function apply(Builder $q,array $f):Builder{$q->when($f['price_from']!==null,fn($q)=>$q->where('price','>=',$f['price_from']))->when($f['price_to']!==null,fn($q)=>$q->where('price','<=',$f['price_to']));if(count($f['availability'])===1){$f['availability'][0]==='in_stock'?$q->where('stock','>',0):$q->where('stock',0);}$q->whereHas('skiRack',fn($q)=>$q->when($f['manufacturers']!==[],fn($q)=>$q->whereIn('manufacturer_id',$f['manufacturers']))->when($f['ski_pairs']!==[],fn($q)=>$q->whereIn('ski_pairs_capacity',$f['ski_pairs']))->when($f['snowboards']!==[],fn($q)=>$q->whereIn('snowboard_capacity',$f['snowboards'])));return $q;} public function options(Collection $p):array{$items=$p->pluck('skiRack')->filter();return ['manufacturers'=>$items->pluck('manufacturer')->filter(fn($m)=>$m?->is_active)->unique('id')->sortBy('name')->values(),'price_min'=>$p->min('price'),'price_max'=>$p->max('price'),'ski_pairs'=>$this->optionsFor($items,'ski_pairs_capacity'),'snowboards'=>$this->optionsFor($items,'snowboard_capacity')];} private function optionsFor(Collection $i,string $f):Collection{return $i->pluck($f)->filter(fn($v)=>$v!==null)->unique()->sort(SORT_NUMERIC)->values();} private function strings(mixed $v):array{return collect(is_array($v)?$v:($v===null?[]:[$v]))->filter(fn($v)=>is_scalar($v))->map(fn($v)=>trim((string)$v))->filter()->unique()->values()->all();} private function numbers(mixed $v):array{return collect($this->strings($v))->filter(fn($v)=>is_numeric($v)&&(float)$v>=0)->values()->all();} private function number(mixed $v):?string{return is_scalar($v)&&is_numeric($v)&&(float)$v>=0?(string)$v:null;} }
